import{_ as t}from"./chunks/api-multilingual-retrieval.CLcf2N7y.js";import{bQ as a,aL as r,u as i,G as n}from"./chunks/framework.igrrHzX3.js";const s="/knowledge/images/multilingual-retrieval-embedding-space.svg",o="/knowledge/images/multilingual-retrieval-three-ways.svg",y=JSON.parse('{"title":"Multilingual retrieval","description":"","frontmatter":{},"headers":[],"relativePath":"guides/components/multilingual-retrieval.md","filePath":"guides/components/multilingual-retrieval.md"}'),l={name:"guides/components/multilingual-retrieval.md"};function d(h,e,g,u,c,m){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="multilingual-retrieval" tabindex="-1">Multilingual retrieval <a class="header-anchor" href="#multilingual-retrieval" aria-label="Permalink to &quot;Multilingual retrieval&quot;">​</a></h1><p>The corpus is mostly English, with French pages here and there, and questions arrive in French as often as in English. A question must find its page <strong>whatever the language of the question and of the page</strong>.</p><p><img src="'+t+'" alt="Multilingual retrieval"></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="_1-a-multilingual-embedding-space" tabindex="-1">1. A multilingual embedding space <a class="header-anchor" href="#_1-a-multilingual-embedding-space" aria-label="Permalink to &quot;1. A multilingual embedding space&quot;">​</a></h3><p><a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B" target="_blank" rel="noreferrer">Qwen3-Embedding-0.6B</a> places a text according to its meaning, not its language: a French question lands near the English passage that answers it.</p><p><img src="'+s+'" alt="A multilingual embedding space"></p><table tabindex="0"><thead><tr><th>Case</th><th>Crosses languages?</th></tr></thead><tbody><tr><td><strong>Shared anchor</strong>: a product name, a URL, an identifier (<code>KLayerList</code>, <code>k-clone</code>)</td><td>yes, it is the same token in both languages</td></tr><tr><td><strong>Diverging vocabulary</strong>: « grappes » / <em>cluster</em></td><td>only partly: the words share no sub-word, the right page ranks lower</td></tr></tbody></table><h3 id="_2-query-translation-both-ways" tabindex="-1">2. Query translation, both ways <a class="header-anchor" href="#_2-query-translation-both-ways" aria-label="Permalink to &quot;2. Query translation, both ways&quot;">​</a></h3><p>The diverging-vocabulary gap is lexical, and a translation fixes lexical gaps. The question is translated by small <a href="https://marian-nmt.github.io/" target="_blank" rel="noreferrer">Marian</a> models (<a href="https://github.com/Helsinki-NLP/Opus-MT" target="_blank" rel="noreferrer">Helsinki-NLP OPUS-MT</a>), not by an LLM:</p><table tabindex="0"><thead><tr><th>Model</th><th>Direction</th><th>Reaches</th></tr></thead><tbody><tr><td><code>Helsinki-NLP/opus-mt-fr-en</code></td><td>French → English</td><td>the English pages from a French question</td></tr><tr><td><code>Helsinki-NLP/opus-mt-en-fr</code></td><td>English → French</td><td>the French pages from an English question</td></tr></tbody></table><p>About 75 M parameters and 300 MB each, tens of milliseconds on CPU, baked into the API image.</p><p><img src="'+o+'" alt="Three ways to answer a question"></p><h3 id="_3-searching-every-phrasing" tabindex="-1">3. Searching every phrasing <a class="header-anchor" href="#_3-searching-every-phrasing" aria-label="Permalink to &quot;3. Searching every phrasing&quot;">​</a></h3><ul><li>The <strong>original question is always searched</strong>: it carries the identifiers, and it is the phrasing that reaches the pages written in its own language.</li><li>Each translation is searched too, and each passage keeps the <strong>best score</strong> any phrasing gave it.</li><li>The language is detected from the question&#39;s function words (English, French, Spanish, German, Italian). A question with no clear language, bare keywords, is searched as typed.</li><li><code>/ask</code> sends the LLM the question as typed and asks it to answer in that language.</li></ul><div class="tip custom-block"><p class="custom-block-title">Configuration</p><p><code>QUERY_TRANSLATION_MODEL</code> takes one Marian model or several, comma-separated; empty turns translation off. The API image bakes in <code>Helsinki-NLP/opus-mt-fr-en,Helsinki-NLP/opus-mt-en-fr</code>; another OPUS-MT pair plugs in by name and is downloaded at first use.</p></div><details class="details custom-block"><summary>Example</summary><p>The question that started the work, against the English documentation of <code>kdk</code>:</p><table tabindex="0"><thead><tr><th>Query</th><th style="text-align:right;">Best score</th><th>Section reached</th></tr></thead><tbody><tr><td><code>comment grouper les marqueurs en grappes sur une carte</code>, no translation</td><td style="text-align:right;">0.656</td><td><em>Dynamic building &gt; gradient path</em> ✗</td></tr><tr><td><code>how to group markers into clusters on a map</code></td><td style="text-align:right;">0.760</td><td><em>GeoJson Layer &gt; Clustering</em> ✓</td></tr><tr><td><code>comment regrouper les marqueurs en grappes sur une carte</code>, translated fr→en</td><td style="text-align:right;">0.774</td><td><em>GeoJson Layer &gt; Clustering</em> ✓</td></tr></tbody></table><p>The translation (<em>&quot;how to group cluster markers on a map&quot;</em>) brings <em>cluster</em> into the search.</p></details>',17)])])}const f=a(l,[["render",d]]);export{y as __pageData,f as default};
